}

const accepted = (c) => c && (c.exact || c.fc >= MIN_FORM_COVERAGE);

const decisions = new Map();
function decide(formKey) {
  if (decisions.has(formKey)) return decisions.get(formKey);
  const list = formKey ? rankProducts(formKey) : [];
  const [top, second] = list;
  // equally good = same exact flag, same score, same number match, same active flag
  const sameAsTop = (c) => c.exact === top.exact && Math.abs(c.score - top.score) < 0.001 && c.nums === top.nums && c.active === top.active;
  let d;
  if (!top) d = { status: 'none' };
  else if (!accepted(top)) d = { status: 'weak', closest: top };
  else if (second && accepted(second) && sameAsTop(second)) d = { status: 'tie', options: list.filter(sameAsTop).slice(0, 5) };
  else d = { status: 'ok', product: top };
  decisions.set(formKey, d);
  return d;
}

