const byCode = new Map(products.filter((p) => p.item_code).map((p) => [p.item_code.toLowerCase(), p]));
const plainCode = (v) => String(v ?? '').trim().replace(/\.0+$/, '');
const posInt = (v) => { const n = Number(String(v ?? '').replace(/[^\d.]/g, '')); return Number.isInteger(n) && n > 0 ? n : null; };

const rows = [];
const failed = new Map();       // product text → { d, count }   (only stops when STOP_ON_UNKNOWN_PRODUCT)
const unmatched = new Map();    // product text → count          (left blank)
const noProduct = new Map();    // file → count of rows with no product column / item code
const incomplete = new Map();   // product_name → { row, missing }
const matchedCount = new Map(); // "form → product" → orders
const blanks = { tp_1: 0, name: 0, address: 0, price: 0, item_code: 0, delivery: 0 };
const seen = new Set();
let duplicates = 0;
let noProductsSheet = false;

for (const lead of leads) {
  if (DEDUPE_BY_LEAD_ID && lead.lead_id) {
    if (seen.has(lead.lead_id)) { duplicates++; continue; }
    seen.add(lead.lead_id);
  }

  const own = { price: money(lead.price), item_code: plainCode(lead.item_code), delivery: money(lead.delivery) };
  const key = cleanForm(lead.form_name);
  let p = own.item_code ? byCode.get(own.item_code.toLowerCase()) || null : null;
  let label = p ? `item ${own.item_code} → ${p.product_name}` : own.item_code ? `item ${own.item_code}` : '';

  const needProduct = !p && (!own.item_code || !own.price || !own.delivery);
  if (needProduct && key) {
    if (!products.length) noProductsSheet = true;
    const d = products.length ? decide(key) : { status: 'none' };
    if (d.status === 'ok') {
      p = d.product;
      label = `${key} → ${p.product_name}`;
    } else if (STOP_ON_UNKNOWN_PRODUCT && products.length && !lead.form_from_file && !own.item_code) {
      const f = failed.get(key) || { d, count: 0 };
      f.count++;
      failed.set(key, f);
      continue;
    } else if (lead.form_from_file) {
      noProduct.set(lead.file, (noProduct.get(lead.file) || 0) + 1);
      label = label || '(no product)';
    } else {
      unmatched.set(key, (unmatched.get(key) || 0) + 1);
      label = label || `${key} → (no product)`;
    }
  }
  if (!label) label = '(no product column)';

  const tp1 = toLocal(lead.phone_number) || toLocal(lead.work_phone_number) || String(lead.phone_number || '').replace(/\D/g, '');
  const tp2 = toLocal(lead.work_phone_number) || tp1;

  const row = {
    name: String(lead.name || '').trim(),
    address: String(lead.address || '').replace(/\s*[\r\n]+\s*/g, ', ').trim(),
    tp_1: tp1,
    tp_2: tp2,
    price: own.price || (p ? p.price : ''),
    qty: posInt(lead.qty) || QTY,
    item_code: own.item_code || (p ? p.item_code : ''),
    delivery: own.delivery || (p ? p.delivery_fee : ''),
  };
  rows.push(row);

  for (const k of Object.keys(blanks)) if (String(row[k] ?? '').trim() === '') blanks[k]++;
  if (row.tp_1 && !/^0\d{9}$/.test(row.tp_1)) blanks.tp_1++;
  if (p) {
    const miss = ['price', 'item_code', 'delivery_fee'].filter((k) => String(p[k] ?? '').trim() === '' && !own[k === 'delivery_fee' ? 'delivery' : k]);
    if (miss.length) incomplete.set(p.product_name, { row: p.row, missing: miss });
  }
  matchedCount.set(label, (matchedCount.get(label) || 0) + 1);
}

// ---------- problems → show them on the form instead of a wrong file ----------
// Products from feeder.retexia.com (Supabase) or from the Products Google Sheet.
const FROM_PANEL = $input.all().some((i) => i.json && i.json.source === 'panel');
const LIST = FROM_PANEL ? 'your products' : 'the Products sheet';
const where = (p) => (FROM_PANEL ? `product ${p.item_code || p.product_id}` : `sheet row ${p.row}`);
const aliasHint = (form) => FROM_PANEL
  ? `Fix: on feeder.retexia.com → My products, add <b>${htmlEsc(form)}</b> as a form name of the right product, then build again.`
  : `Fix: in the Products Google Sheet add <b>${htmlEsc(form)}</b> to the <code>aliases</code> column of the correct product (comma-separated), then upload again.`;
for (const [form, { d, count }] of failed) {
  const head = `Product <b>"${htmlEsc(form)}"</b> (${count} order${count > 1 ? 's' : ''}): `;
  if (d.status === 'none') problems.push(head + `not found in ${LIST}. ${aliasHint(form)}`);
  if (d.status === 'weak') problems.push(head + `no confident match — closest is "${htmlEsc(d.closest.product_name)}" (${where(d.closest)}). ${aliasHint(form)}`);
  if (d.status === 'tie') problems.push(head + `matches several products equally (${d.options.map((c) => `"${htmlEsc(c.product_name)}"`).join(', ')}). ${aliasHint(form)}`);
}
if (problems.length === 0 && rows.length === 0) problems.push('No leads were found in the uploaded file(s).');

if (problems.length) {
  const html = `<h2>Courier file was NOT created</h2><ul>${problems.map((p) => `<li style="margin-bottom:8px">${p}</li>`).join('')}</ul>`;
  return [{ json: { ok: false, html, problems } }];
}

// ---------- warnings (file is still created) ----------
const warnings = [...(parsed.warnings || [])];
const n = (c, what) => `${c} order${c > 1 ? 's' : ''} ${what}`;
if (noProductsSheet) warnings.push('The Products Google Sheet is empty or could not be read, so price / item_code / delivery came only from the lead files.');
for (const [form, c] of unmatched) warnings.push(`${n(c, 'with')} product <b>"${htmlEsc(form)}"</b> not found in ${LIST} — price / item_code / delivery left blank. ${aliasHint(form)}`);
for (const [file, c] of noProduct) warnings.push(`${n(c, 'in')} <b>${htmlEsc(file)}</b> ${c > 1 ? 'have' : 'has'} no product name or item code — price / item_code / delivery left blank.`);
for (const [name, { row, missing }] of incomplete) {
  warnings.push(`Product <b>"${htmlEsc(name)}"</b> (${FROM_PANEL ? 'your products' : `sheet row ${row}`}) has no ${missing.map((c) => `<code>${c === 'item_code' ? 'product_ID_Feeder' : c}</code>`).join(', ')}${FROM_PANEL ? '' : ' in the Products Google Sheet'} — left blank.`);
}
if (blanks.tp_1) warnings.push(n(blanks.tp_1, 'with no valid phone number'));
for (const k of ['name', 'address', 'price', 'item_code', 'delivery']) if (blanks[k]) warnings.push(n(blanks[k], `with a blank <code>${k}</code>`));

// ---------- CSV (UTF-8 BOM + CRLF, same as the courier sample) ----------
const HEADER = ['name', 'address', 'tp_1', 'tp_2', 'price', 'qty', 'item_code', 'delivery'];
const esc = (v) => {
  const s = v == null ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = '\uFEFF' + [HEADER, ...rows.map((r) => HEADER.map((h) => r[h]))]
  .map((r) => r.map(esc).join(','))
  .join('\r\n');

const fileName = `${$now.setZone(TIMEZONE).toFormat('yyyy_MM_dd')}(${rows.length}).csv`;
const fileCount = (parsed.files || []).length;
const aiFiles = (parsed.files || []).filter((f) => ['AI', 'saved AI map', 'best guess'].includes(f.columns));
const summary =
  `${rows.length} orders from ${fileCount} file${fileCount === 1 ? '' : 's'}` +
  (duplicates ? ` · ${duplicates} duplicate lead${duplicates > 1 ? 's' : ''} skipped` : '') +
  warnings.map((w) => `<br>⚠ ${w}`).join('') +
  (aiFiles.length ? `<br>Columns read by AI: ${aiFiles.map((f) => htmlEsc(f.file)).join(', ')}` : '') +
  `<br>` +
  [...matchedCount].map(([label, n]) => `${htmlEsc(label)} (${n})`).join('<br>');

return [{
  json: { ok: true, fileName, orders: rows.length, duplicates, warnings, matches: Object.fromEntries(matchedCount), summary },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName,
      fileExtension: 'csv',
    },
  },
}];

// Manual CRM run ends here.
// Click this node → Output → Binary → Download to save yyyy_MM_dd(orders).csv
const r = $input.first();
const strip = (s) => String(s ?? '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
if (!r.json.ok) {
  throw new Error('Courier CSV was NOT created:\n' + (r.json.problems || []).map((p) => '• ' + strip(p)).join('\n'));
}
return [{ json: { fileName: r.json.fileName, orders: r.json.orders, summary: strip(r.json.summary) }, binary: r.binary }];

// ─────────────────────────────────────────────────────────────────────────────
// COLLECT SOURCES — the same three sources as feeder.retexia.com → Bulk import v2
//   • Facebook lead files (.xls / .csv)   • TikTok lead files (.xlsx / .csv)
//   • CRM Google Sheets by view link (downloaded here as CSV, one file per sheet/tab)
// Every source is optional; at least one is needed. Used by the form, the panel and
// the manual CRM run, so all three build exactly the same courier CSV.
// Output: the files (binary) for Parse Lead Files + sheet_problems.
// ─────────────────────────────────────────────────────────────────────────────
const MAX_SHEETS = 20;
const item = $input.first();
const j = item.json || {};
const body = j.body || {};

// CRM links: panel (body.crm_links, JSON list), form (textarea, one per line), manual run (crm_links)
const found = [];
for (const v of [body.crm_links, body.crm, j['CRM Google Sheet links'], j.crm_links]) {
  if (!v) continue;
  if (Array.isArray(v)) { found.push(...v); continue; }
  const s = String(v).trim();
  if (s.startsWith('[')) { try { found.push(...JSON.parse(s)); continue; } catch (e) { /* plain text */ } }
  found.push(...s.split(/\s+/));
}
const links = [...new Set(found.map((l) => String(l).trim()).filter(Boolean))].slice(0, MAX_SHEETS);

// A Google Sheet link (normal or "publish to web") → its CSV export, on docs.google.com only
function exportUrl(link) {
  let url;
  try { url = new URL(link); } catch (e) { return null; }
  if (url.protocol !== 'https:' || url.hostname !== 'docs.google.com') return null;
  const gid = (/[#&?]gid=(\d+)/.exec(link) || [])[1] || '0';
  const published = /^\/spreadsheets\/d\/e\/([\w-]+)/.exec(url.pathname);
  if (published) return `https://docs.google.com/spreadsheets/d/e/${published[1]}/pub?output=csv&gid=${gid}`;
  const id = (/^\/spreadsheets\/d\/([\w-]{20,})/.exec(url.pathname) || [])[1];
  return id ? `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&gid=${gid}` : null;
}

const binary = { ...(item.binary || {}) };
const sheet_problems = [];
for (const [i, link] of links.entries()) {
  const label = `CRM sheet ${i + 1}`;
  const url = exportUrl(link);
  if (!url) { sheet_problems.push(`${label}: this isn't a Google Sheet link (docs.google.com/spreadsheets/…).`); continue; }
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, encoding: 'arraybuffer', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 });
    const h = res.headers || {};
    const type = String(h['content-type'] || '');
    const buf = Buffer.from(res.body || []);
    if (res.statusCode >= 400 || !/text\/csv|text\/plain|octet-stream/.test(type)) {
      sheet_problems.push(`${label}: can't be opened. In the sheet: Share → General access → "Anyone with the link" → Viewer, then try again.`);
      continue;
    }
    if (!buf.length) { sheet_problems.push(`${label}: the tab is empty. Copy the link while the orders tab is open (it ends with #gid=…).`); continue; }
    const disp = String(h['content-disposition'] || '');
    let name = label;
    try { const m = /filename\*=UTF-8''([^;]+)/i.exec(disp) || /filename="?([^";]+)"?/i.exec(disp); if (m) name = decodeURIComponent(m[1]).replace(/\.csv$/i, ''); } catch (e) { /* keep label */ }
    const fileName = `CRM - ${name.replace(/[\\/:*?"<>|]+/g, ' ').slice(0, 100)}.csv`;
    binary[`crm${i}`] = await this.helpers.prepareBinaryData(buf, fileName, 'text/csv');
  } catch (e) {
    sheet_problems.push(`${label}: Google didn't answer (${e.message}). Try again in a minute.`);
  }
}
if (!Object.keys(binary).length && !sheet_problems.length) sheet_problems.push('Add at least one Facebook or TikTok lead file, or a CRM Google Sheet link.');

return [{ json: { sheet_problems, crm_sheets: links.length }, binary }];
